/** Probe fixtures for the media capability registry.
 *
 *  Committed as generated data, not built at runtime. Embedded as base64 rather
 *  than read from `public/`, because the probe runs inside a Worker: it has no
 *  filesystem, and fetching its own origin to reach a static asset is a
 *  subrequest that can loop. Constants cannot fail.
 *
 *  Each fixture is chosen so that only a model which genuinely received the
 *  bytes can produce the expected answer:
 *
 *  - `PROBE_IMAGE_PNG_B64` is a solid red square. A blind model cannot name the
 *    colour; the word "red" is the proof.
 *  - `PROBE_SPEECH_WAV_B64` is real speech. A tone would not do: a deaf model
 *    and a hearing one answer a tone identically ("no audio"), so only speech
 *    distinguishes them.
 *  - `PROBE_VIDEO_MP4_B64` is a blue clip that also carries the same speech, so
 *    a video-capable model can be recognised from either the picture or the
 *    sound. It is small on purpose: a truncated MP4 is refused by the upstream
 *    with a 400, which is indistinguishable from a model that cannot see video.
 */

/** A solid red 64x64 PNG, as bare base64 (no data-URL prefix). */
export const PROBE_IMAGE_PNG_B64 =
  "iVBORw0KGgoAAAANSUhEUgAAAEAAAABACAIAAAAlC+aJAAAAT0lEQVR42u3PQQkAAAgEsEty/UMZxgi+hcEKLNO+FgEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQGBywLPLIEA68ZURwAAAABJRU5ErkJggg==";
/** 2.5 s of speech, 16 kHz mono 16-bit PCM, as bare base64 (no data-URL prefix). */
export const PROBE_SPEECH_WAV_B64 =
  "";
/** A 3 s blue clip carrying the same speech, as bare base64. */
export const PROBE_VIDEO_MP4_B64 =
  "";
